#include "NativeStaticBoxSolveV111.h"
#include <iostream>
#include <cstring>
float f(unsigned w){float v;std::memcpy(&v,&w,4);return v;}unsigned bits(float v){unsigned w;std::memcpy(&w,&v,4);return w;}
int main(){unsigned a[96];while(std::cin>>a[0]){for(unsigned i=1;i<96;++i)std::cin>>a[i];namespace P=motorrock_native_pair_v73;P::Row row;auto axes=P::axes({{f(a[16]),f(a[17]),f(a[18]),f(a[19])}});row.normal=axes[0];row.tangent0=axes[1];row.tangent1=axes[2];row.mass={{f(a[20]),f(a[21]),f(a[22])}};row.bias={{f(a[24]),0,0}};row.static_mu={{f(a[7]),f(a[11])}};row.dynamic_mu={{f(a[15]),f(a[23])}};row.normal_impulse=f(a[27]);row.friction={{f(a[12]),f(a[13]),f(a[14])}};std::array<P::Body,2> bodies{};for(unsigned b=0;b<2;++b){auto &body=bodies[b];unsigned base=32+b*32;for(unsigned i=0;i<3;++i){body.velocity[i]=f(a[base+i]);body.angular[i]=f(a[base+4+i]);body.lever[i]=f(a[4+b*4+i]);}for(unsigned i=0;i<9;++i)body.inverse_inertia[i]=f(a[base+15+i]);body.inverse_mass=f(a[base+11]);}motorrock_native_static_box_v111::solve(row,bodies,f(a[31]));for(auto v:{bodies[1].velocity,bodies[1].angular})for(unsigned i=0;i<3;++i)std::cout<<bits(v[i])<<' ';std::cout<<bits(row.normal_impulse)<<' ';for(unsigned i=0;i<3;++i)std::cout<<bits(row.friction[i])<<' ';std::cout<<'\n';}}
